#include <bits/stdc++.h>
using namespace std;

const int MAXN = 300;
const int INF = 1e9;

struct FlowEdge {
    int to, rev, flow, capacity;
    FlowEdge(int to, int rev, int flow, int capacity) : to(to), rev(rev), flow(flow), capacity(capacity) {}
};
vector<FlowEdge> graph[MAXN];

void connectVertices(int u, int v, int c, int rc = 0) {
    FlowEdge e1(v, graph[v].size(), 0, c);
    FlowEdge e2(u, graph[u].size(), 0, rc);
    graph[u].push_back(e1);
    graph[v].push_back(e2);
}

int distArr[MAXN], ptrArr[MAXN], sIdx, tIdx;

bool buildLevelGraph() {
    memset(distArr, -1, sizeof(distArr));
    distArr[sIdx] = 0;
    queue<int> q({sIdx});
    while (!q.empty() && distArr[tIdx] == -1) {
        int u = q.front(); q.pop();
        for (auto &edge : graph[u]) {
            int v = edge.to;
            if (distArr[v] == -1 && edge.flow < edge.capacity) {
                distArr[v] = distArr[u] + 1;
                q.push(v);
            }
        }
    }
    return distArr[tIdx] != -1;
}

int pushFlow(int u, int flow) {
    if (u == tIdx || flow == 0)
        return flow;
    for (int &i = ptrArr[u]; i < graph[u].size(); i++) {
        auto &e = graph[u][i];
        int v = e.to;
        if (distArr[v] != distArr[u] + 1)
            continue;
        if (int pushed = pushFlow(v, min(flow, e.capacity - e.flow))) {
            e.flow += pushed;
            graph[v][e.rev].flow -= pushed;
            return pushed;
        }
    }
    return 0;
}

int computeMaxFlow() {
    int totalFlow = 0;
    while (buildLevelGraph()) {
        memset(ptrArr, 0, sizeof(ptrArr));
        while (int pushed = pushFlow(sIdx, INT_MAX))
            totalFlow += pushed;
    }
    return totalFlow;
}

int deltaX[] = {-1, 0, 0, 1};
int deltaY[] = {0, -1, 1, 0};

int n, m;
using Grid = vector<vector<int>>;
using Point = array<int, 2>;
Grid obs, distT, distD;

void runBFS(int r, int c, Grid &dis, bool check = false) {
    for (int i = 0; i < n; i++)
        fill(dis[i].begin(), dis[i].end(), -1);
    dis[r][c] = 0;
    queue<Point> q;
    q.push({r, c});
    while (!q.empty()) {
        auto p = q.front(); q.pop();
        if (check && dis[p[0]][p[1]] == distT[p[0]][p[1]])
            continue;
