        for (int i = 0; i < 4; i++) {
            neighbor = {p[0] + deltaX[i], p[1] + deltaY[i]};
            if (neighbor[0] < 0 || neighbor[0] >= n || neighbor[1] < 0 || neighbor[1] >= n || dis[neighbor[0]][neighbor[1]] != -1 || obs[neighbor[0]][neighbor[1]])
                continue;
            if (check && distT[neighbor[0]][neighbor[1]] > -1 && dis[p[0]][p[1]] + 1 > distT[neighbor[0]][neighbor[1]])
                continue;
            dis[neighbor[0]][neighbor[1]] = dis[p[0]][p[1]] + 1;
            q.push(neighbor);
        }
    }
}

vector<string> lab, rea;

int main() {
    cin >> n >> m;
    lab.resize(n);
    rea.resize(n);
    for (auto &x : lab)
        cin >> x;
    for (auto &x : rea)
        cin >> x;
    obs.assign(n, vector<int>(n));
