    sIdx = 2 * n * n + 5;
    tIdx = sIdx + 1;
    for (int x = 0; x < n; x++) {
        for (int y = 0; y < n; y++) {
            if (lab[x][y] == 'Z' || lab[x][y] == 'Y')
                continue;
            connectVertices(sIdx, n * x + y, lab[x][y] - '0');
            connectVertices(n * n + n * x + y, tIdx, rea[x][y] - '0');
            runBFS(x, y, distD, true);
            for (int xp = 0; xp < n; xp++) {
                for (int yp = 0; yp < n; yp++) {
