import java.util.*;
import java.io.*;

public class MaxFlowSolver {
    static final int MAXN = 300;
    static final int INF = (int)1e9;

    static class FlowEdge {
        int to, rev, flow, capacity;
        FlowEdge(int to, int rev, int flow, int capacity) {
            this.to = to;
            this.rev = rev;
            this.flow = flow;
            this.capacity = capacity;
        }
    }

    static List<FlowEdge>[] graph = new ArrayList[MAXN];

    static void connectVertices(int u, int v, int c, int rc) {
        graph[u].add(new FlowEdge(v, graph[v].size(), 0, c));
        graph[v].add(new FlowEdge(u, graph[u].size() - 1, 0, rc));
    }

    static int[] distArr = new int[MAXN];
    static int[] ptrArr = new int[MAXN];
    static int sIdx, tIdx;

    static boolean buildLevelGraph() {
        Arrays.fill(distArr, -1);
        distArr[sIdx] = 0;
        Queue<Integer> q = new LinkedList<>();
        q.offer(sIdx);
        while (!q.isEmpty() && distArr[tIdx] == -1) {
            int u = q.poll();
            for (FlowEdge e : graph[u]) {
                int v = e.to;
                if (distArr[v] == -1 && e.flow < e.capacity) {
                    distArr[v] = distArr[u] + 1;
                    q.offer(v);
                }
            }
        }
        return distArr[tIdx] != -1;
    }

    static int pushFlow(int u, int flow) {
        if (u == tIdx || flow == 0)
            return flow;
        for (; ptrArr[u] < graph[u].size(); ptrArr[u]++) {
            FlowEdge e = graph[u].get(ptrArr[u]);
            int v = e.to;
            if (distArr[v] != distArr[u] + 1)
                continue;
            int pushed = pushFlow(v, Math.min(flow, e.capacity - e.flow));
            if (pushed > 0) {
                e.flow += pushed;
                graph[v].get(e.rev).flow -= pushed;
                return pushed;
            }
        }
        return 0;
    }

    static int computeMaxFlow() {
        int totalFlow = 0;
        while (buildLevelGraph()) {
            Arrays.fill(ptrArr, 0);
            int pushed;
            while ((pushed = pushFlow(sIdx, Integer.MAX_VALUE)) > 0) {
                totalFlow += pushed;
            }
        }
        return totalFlow;
    }

    static int[] deltaX = {-1, 0, 0, 1};
    static int[] deltaY = {0, -1, 1, 0};

    static int n, m;
    static List<String> lab, rea;
    static int[][] obs, distT, distD;

    static void runBFS(int r, int c, int[][] dis, boolean check) {
        for (int i = 0; i < n; i++)
            Arrays.fill(dis[i], -1);
        dis[r][c] = 0;
        Queue<int[]> q = new LinkedList<>();
        q.offer(new int[]{r, c});
        while (!q.isEmpty()) {
            int[] p = q.poll();
            if (check && dis[p[0]][p[1]] == distT[p[0]][p[1]])
                continue;
            for (int i = 0; i < 4; i++) {
                int nr = p[0] + deltaX[i];
                int nc = p[1] + deltaY[i];
                if (nr < 0 || nr >= n || nc < 0 || nc >= n || dis[nr][nc] != -1 || obs[nr][nc] == 1)
                    continue;
                if (check && distT[nr][nc] > -1 && dis[p[0]][p[1]] + 1 > distT[nr][nc])
                    continue;
                dis[nr][nc] = dis[p[0]][p[1]] + 1;
                q.offer(new int[]{nr, nc});
            }
        }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        n = Integer.parseInt(st.nextToken());
        m = Integer.parseInt(st.nextToken());

        lab = new ArrayList<>();
        rea = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            lab.add(br.readLine());
        }
        for (int i = 0; i < n; i++) {
            rea.add(br.readLine());
        }

        obs = new int[n][n];
        distT = new int[n][n];
        distD = new int[n][n];

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                obs[i][j] = (lab.get(i).charAt(j) == 'Y') ? 1 : 0;
            }
        }

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (lab.get(i).charAt(j) == 'Z') {
                    runBFS(i, j, distT, false);
                }
            }
        }

        int totalVertices = 2 * n * n + 2;
        sIdx = 2 * n * n;
        tIdx = sIdx + 1;

        for (int i = 0; i < MAXN; i++) {
            graph[i] = new ArrayList<>();
        }

        for (int x = 0; x < n; x++) {
            for (int y = 0; y < n; y++) {
                if (lab.get(x).charAt(y) == 'Z' || lab.get(x).charAt(y) == 'Y')
                    continue;
                if (graph[sIdx] == null) graph[sIdx] = new ArrayList<>();
                if (graph[n * x + y] == null) graph[n * x + y] = new ArrayList<>();
                if (graph[n * n + n * x + y] == null) graph[n * n + n * x + y] = new ArrayList<>();
                if (graph[tIdx] == null) graph[tIdx] = new ArrayList<>();

                connectVertices(sIdx, n * x + y, lab.get(x).charAt(y) - '0', 0);
                connectVertices(n * n + n * x + y, tIdx, rea.get(x).charAt(y) - '0', 0);
                runBFS(x, y, distD, true);
                for (int xp = 0; xp < n; xp++) {
                    for (int yp = 0; yp < n; yp++) {
                        if (distD[xp][yp] != -1 && distD[xp][yp] <= m) {
                            connectVertices(n * x + y, n * n + n * xp + yp, INF, 0);
                        }
                    }
                }
            }
        }

        System.out.println(computeMaxFlow());
    }
}
